-- ==============================================================
-- SECCIÓN 7: CARGADOR DE STAGING
-- Descripción: pr_cargar_staging copia el OLTP a las 29 tablas STG y revisa las reglas de staging;
--   los 29 triggers trg_stg_*_inmutable impiden editar las copias.
-- ==============================================================

-- Se ejecuta desde INSTALAR_VALIDACIONES.sql, que fija las opciones de la sesión.

-- === Cargador ===
CREATE OR REPLACE PROCEDURE pr_cargar_staging AUTHID DEFINER AS
  -- ----------------------------------------------------------------------
  -- PR_CARGAR_STAGING
  -- Copia el OLTP a las tablas STG en una carga nueva. Comprueba la estructura, bloquea las
  -- tablas de origen en modo compartido para tener una foto consistente, revisa una por una
  -- las reglas de staging y registra la ejecución en auditoria_etl_evaluaciones. Si una regla
  -- falla, revierte la copia y guarda una fila de ejemplo en errores_etl_evaluaciones.
  -- ----------------------------------------------------------------------
    v_iniciada BOOLEAN:=FALSE;
    v_n NUMBER; v_esperados NUMBER; v_leidos NUMBER:=0; v_insertados NUMBER:=0;
    v_ejecucion NUMBER; v_fecha_carga TIMESTAMP(6); v_rechazados NUMBER:=0;
    v_objeto VARCHAR2(100):='INICIO'; v_codigo NUMBER; v_mensaje VARCHAR2(4000); v_original CLOB;

    PROCEDURE comprobar_columna(p_tabla VARCHAR2,p_pos NUMBER,p_col VARCHAR2,
      p_tipo VARCHAR2,p_precision NUMBER,p_escala NUMBER,p_largo NUMBER,p_null VARCHAR2) IS
      v_tipo VARCHAR2(128);v_prec NUMBER;v_esc NUMBER;v_largo NUMBER;
      v_char VARCHAR2(1);v_null VARCHAR2(1);v_pos NUMBER;
    BEGIN
      SELECT data_type,data_precision,data_scale,char_length,char_used,nullable,column_id
        INTO v_tipo,v_prec,v_esc,v_largo,v_char,v_null,v_pos
        FROM user_tab_columns WHERE table_name=UPPER(p_tabla) AND column_name=UPPER(p_col);
      IF v_tipo<>p_tipo OR v_null<>p_null OR (p_pos IS NOT NULL AND v_pos<>p_pos)
        OR (p_tipo='NUMBER' AND (NVL(v_prec,-1)<>NVL(p_precision,-1) OR NVL(v_esc,-1)<>NVL(p_escala,-1)))
        OR (p_tipo='VARCHAR2' AND (v_largo<>p_largo OR v_char<>'C')) THEN
        RAISE_APPLICATION_ERROR(-20011,'Estructura incompatible: '||p_tabla||'.'||p_col||'. Revisar el contrato y migrar explícitamente.');
      END IF;
    EXCEPTION WHEN NO_DATA_FOUND THEN
      RAISE_APPLICATION_ERROR(-20012,'Falta la columna requerida: '||p_tabla||'.'||p_col);
    END;
    PROCEDURE comprobar_clave(p_tabla VARCHAR2,p_tipo VARCHAR2,p_cols VARCHAR2,
      p_padre VARCHAR2 DEFAULT NULL,p_cols_padre VARCHAR2 DEFAULT NULL) IS
      v_total NUMBER;
    BEGIN
      SELECT COUNT(*) INTO v_total FROM user_constraints c
      WHERE c.table_name=UPPER(p_tabla) AND c.constraint_type=p_tipo
        AND c.status='ENABLED' AND c.validated='VALIDATED'
        AND (SELECT LISTAGG(k.column_name,',') WITHIN GROUP (ORDER BY k.position)
               FROM user_cons_columns k WHERE k.constraint_name=c.constraint_name)=UPPER(p_cols)
        AND (p_tipo<>'R' OR EXISTS (SELECT 1 FROM user_constraints r
          WHERE r.constraint_name=c.r_constraint_name AND r.table_name=UPPER(p_padre)
          AND (SELECT LISTAGG(z.column_name,',') WITHIN GROUP (ORDER BY z.position)
                 FROM user_cons_columns z WHERE z.constraint_name=r.constraint_name)=UPPER(p_cols_padre)));
      IF v_total=0 THEN
        RAISE_APPLICATION_ERROR(-20015,'Falta clave activa y validada: '||p_tabla||' ('||p_cols||') tipo '||p_tipo);
      END IF;
    END;
    PROCEDURE comprobar_segmento(p_tabla VARCHAR2) IS
      v_segmento VARCHAR2(3); v_pendientes NUMBER;
    BEGIN
      SELECT segment_created INTO v_segmento FROM user_tables WHERE table_name=UPPER(p_tabla);
      SELECT COUNT(*) INTO v_pendientes FROM user_indexes WHERE table_name=UPPER(p_tabla) AND segment_created='NO';
      IF v_segmento<>'YES' OR v_pendientes>0 THEN
        RAISE_APPLICATION_ERROR(-20016,'Segmento pendiente: '||p_tabla||'. Materializar antes de la carga y repetir creación/verificación.');
      END IF;
    END;


    PROCEDURE comprobar_regla(p_regla VARCHAR2,p_tabla VARCHAR2,p_sql VARCHAR2,p_json VARCHAR2) IS
      v_cursor SYS_REFCURSOR;
    BEGIN
      v_objeto:=p_tabla;
      EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM ('||p_sql||')' INTO v_n;
      IF v_n>0 THEN
        v_rechazados:=v_n;
        OPEN v_cursor FOR 'SELECT '||p_json||' FROM ('||p_sql||') q WHERE ROWNUM=1';
        FETCH v_cursor INTO v_original; CLOSE v_cursor;
        RAISE_APPLICATION_ERROR(-20031,SUBSTR(p_regla||': '||TO_CHAR(v_n)||' filas incumplen la regla.',1,1800));
      END IF;
    END;


    -- Estadísticas de STG copiadas del origen antes de abrir la transacción: sin ellas, la primera carga valida
    -- con muestreo dinámico sobre filas sin confirmar y Oracle puede elegir planes de horas. DBMS_STATS confirma de forma
    -- implícita, por eso va antes de iniciar la carga.
    PROCEDURE copiar_tabla(p_stg VARCHAR2,p_origen VARCHAR2) IS
      v_fecha DATE; v_filas NUMBER; v_bloques NUMBER; v_largo NUMBER;
    BEGIN
      SELECT last_analyzed INTO v_fecha FROM user_tables WHERE table_name=UPPER(p_origen);
      IF v_fecha IS NULL THEN DBMS_STATS.GATHER_TABLE_STATS(USER,UPPER(p_origen)); END IF;
      SELECT num_rows,blocks,avg_row_len INTO v_filas,v_bloques,v_largo FROM user_tables WHERE table_name=UPPER(p_origen);
      DBMS_STATS.SET_TABLE_STATS(USER,UPPER(p_stg),numrows=>v_filas,numblks=>v_bloques,avgrlen=>v_largo,no_invalidate=>FALSE);
    END;
    PROCEDURE copiar_columna(p_stg VARCHAR2,p_col VARCHAR2,p_origen VARCHAR2,p_col_origen VARCHAR2) IS
      v_distintos NUMBER; v_densidad NUMBER; v_nulos NUMBER; v_rec DBMS_STATS.STATREC; v_largo NUMBER;
    BEGIN
      DBMS_STATS.GET_COLUMN_STATS(USER,UPPER(p_origen),UPPER(p_col_origen),distcnt=>v_distintos,density=>v_densidad,
        nullcnt=>v_nulos,srec=>v_rec,avgclen=>v_largo);
      DBMS_STATS.SET_COLUMN_STATS(USER,UPPER(p_stg),UPPER(p_col),distcnt=>v_distintos,density=>v_densidad,
        nullcnt=>v_nulos,srec=>v_rec,avgclen=>v_largo,no_invalidate=>FALSE);
    EXCEPTION WHEN OTHERS THEN
      IF SQLCODE NOT BETWEEN -20999 AND -20000 THEN RAISE; END IF;  -- columna de origen sin estadísticas: se omite
    END;
    PROCEDURE marcar_metadato(p_stg VARCHAR2,p_col VARCHAR2) IS
    BEGIN
      DBMS_STATS.SET_COLUMN_STATS(USER,UPPER(p_stg),UPPER(p_col),distcnt=>1,density=>1,nullcnt=>0,no_invalidate=>FALSE);
    END;
    PROCEDURE abrir_ejecucion IS
      PRAGMA AUTONOMOUS_TRANSACTION;
      v_nueva NUMBER;
    BEGIN
      SELECT SEQ_ETL_CARGA.NEXTVAL INTO v_nueva FROM dual;
      INSERT INTO auditoria_etl_evaluaciones
        (id_ejecucion,fuente,inicio,fin,estado,total_leidos,insertados,actualizados,rechazados)
        VALUES (v_nueva,'Validacion/pr_cargar_staging',LOCALTIMESTAMP,NULL,'EN_PROCESO',0,0,0,0);
      COMMIT;
      v_ejecucion:=v_nueva;
    EXCEPTION WHEN OTHERS THEN ROLLBACK; RAISE;
    END;
    PROCEDURE registrar_fallo IS
      PRAGMA AUTONOMOUS_TRANSACTION;
    BEGIN
      UPDATE auditoria_etl_evaluaciones SET fin=LOCALTIMESTAMP,estado='ERROR',
        total_leidos=v_leidos,insertados=0,actualizados=0,rechazados=v_rechazados
        WHERE id_ejecucion=v_ejecucion;
      IF v_original IS NULL THEN
        SELECT JSON_OBJECT('script' VALUE 'Validacion/pr_cargar_staging','objeto' VALUE v_objeto,
          'codigo' VALUE v_codigo,'mensaje' VALUE v_mensaje RETURNING CLOB)
          INTO v_original FROM dual;
      END IF;
      INSERT INTO errores_etl_evaluaciones
        (id_error,id_ejecucion,entidad,clave_origen,tipo_error,detalle,json_original,fecha_registro)
        VALUES (SEQ_ETL_ERROR.NEXTVAL,v_ejecucion,v_objeto,NULL,
          CASE WHEN v_rechazados>0 THEN 'VALIDACION' ELSE 'TECNICO' END,
          SUBSTR(v_mensaje,1,1000),v_original,LOCALTIMESTAMP);
      COMMIT;
    EXCEPTION WHEN OTHERS THEN ROLLBACK; RAISE;
    END;
BEGIN
    IF fn_id_transaccion() IS NOT NULL THEN RAISE_APPLICATION_ERROR(-20815,'Cargador requiere transaccion dedicada sin trabajo pendiente.'); END IF;
    copiar_tabla('STG_CALIFICACIONES','trx_calificacion');
    copiar_columna('STG_CALIFICACIONES','id_calificacion','trx_calificacion','id_calificacion');
    copiar_columna('STG_CALIFICACIONES','id_inscripcion','trx_calificacion','id_inscripcion');
    copiar_columna('STG_CALIFICACIONES','id_ponderacion_periodo','trx_calificacion','id_ponderacion_periodo');
    copiar_columna('STG_CALIFICACIONES','tipo_intento','trx_calificacion','tipo_intento');
    copiar_columna('STG_CALIFICACIONES','numero_intento','trx_calificacion','numero_intento');
    copiar_columna('STG_CALIFICACIONES','version','trx_calificacion','version');
    copiar_columna('STG_CALIFICACIONES','id_calificacion_ordinaria','trx_calificacion','id_calificacion_ordinaria');
    copiar_columna('STG_CALIFICACIONES','id_calificacion_sustituida','trx_calificacion','id_calificacion_sustituida');
    copiar_columna('STG_CALIFICACIONES','id_asignacion_docente','trx_calificacion','id_asignacion_docente');
    copiar_columna('STG_CALIFICACIONES','id_docente_registra','trx_calificacion','id_docente_registra');
    copiar_columna('STG_CALIFICACIONES','nota','trx_calificacion','nota');
    copiar_columna('STG_CALIFICACIONES','resultado_cualitativo','trx_calificacion','resultado_cualitativo');
    copiar_columna('STG_CALIFICACIONES','fecha_evaluacion','trx_calificacion','fecha_evaluacion');
    copiar_columna('STG_CALIFICACIONES','fecha_registro','trx_calificacion','fecha_registro');
    copiar_columna('STG_CALIFICACIONES','fecha_validacion','trx_calificacion','fecha_validacion');
    copiar_columna('STG_CALIFICACIONES','fecha_anulacion','trx_calificacion','fecha_anulacion');
    copiar_columna('STG_CALIFICACIONES','motivo_anulacion','trx_calificacion','motivo_anulacion');
    marcar_metadato('STG_CALIFICACIONES','id_ejecucion_carga');
    marcar_metadato('STG_CALIFICACIONES','fecha_carga');
    copiar_tabla('STG_ASISTENCIAS','trx_asistencia');
    copiar_columna('STG_ASISTENCIAS','id_asistencia','trx_asistencia','id_asistencia');
    copiar_columna('STG_ASISTENCIAS','id_inscripcion','trx_asistencia','id_inscripcion');
    copiar_columna('STG_ASISTENCIAS','id_sesion','trx_asistencia','id_sesion');
    copiar_columna('STG_ASISTENCIAS','estado','trx_asistencia','estado');
    copiar_columna('STG_ASISTENCIAS','hora_llegada','trx_asistencia','hora_llegada');
    copiar_columna('STG_ASISTENCIAS','fecha_registro','trx_asistencia','fecha_registro');
    copiar_columna('STG_ASISTENCIAS','observaciones','trx_asistencia','observaciones');
    marcar_metadato('STG_ASISTENCIAS','id_ejecucion_carga');
    marcar_metadato('STG_ASISTENCIAS','fecha_carga');
    copiar_tabla('STG_INSCRIPCIONES','trx_inscripcion');
    copiar_columna('STG_INSCRIPCIONES','id_inscripcion','trx_inscripcion','id_inscripcion');
    copiar_columna('STG_INSCRIPCIONES','id_estudiante','trx_inscripcion','id_estudiante');
    copiar_columna('STG_INSCRIPCIONES','id_curso','trx_inscripcion','id_curso');
    copiar_columna('STG_INSCRIPCIONES','fecha_inscripcion','trx_inscripcion','fecha_inscripcion');
    copiar_columna('STG_INSCRIPCIONES','fecha_inicio','trx_inscripcion','fecha_inicio');
    copiar_columna('STG_INSCRIPCIONES','fecha_fin','trx_inscripcion','fecha_fin');
    copiar_columna('STG_INSCRIPCIONES','estado','trx_inscripcion','estado');
    copiar_columna('STG_INSCRIPCIONES','motivo_fin_inscripcion','trx_inscripcion','motivo_fin_inscripcion');
    copiar_columna('STG_INSCRIPCIONES','resultado_cierre','trx_inscripcion','resultado_cierre');
    marcar_metadato('STG_INSCRIPCIONES','id_ejecucion_carga');
    marcar_metadato('STG_INSCRIPCIONES','fecha_carga');
    copiar_tabla('STG_ESTUDIANTES','mae_estudiante');
    copiar_columna('STG_ESTUDIANTES','id_estudiante','mae_estudiante','id_estudiante');
    copiar_columna('STG_ESTUDIANTES','id_persona','mae_estudiante','id_persona');
    copiar_columna('STG_ESTUDIANTES','nie','mae_estudiante','nie');
    copiar_columna('STG_ESTUDIANTES','fecha_registro_estudiante','mae_estudiante','fecha_registro');
    copiar_columna('STG_ESTUDIANTES','estudiante_activo','mae_estudiante','activo');
    copiar_columna('STG_ESTUDIANTES','fecha_nacimiento','mae_persona','fecha_nacimiento');
    copiar_columna('STG_ESTUDIANTES','sexo','mae_persona','sexo');
    marcar_metadato('STG_ESTUDIANTES','id_ejecucion_carga');
    marcar_metadato('STG_ESTUDIANTES','fecha_carga');
    copiar_tabla('STG_CICLOS','est_ciclo');
    copiar_columna('STG_CICLOS','id_ciclo','est_ciclo','id_ciclo');
    copiar_columna('STG_CICLOS','codigo','est_ciclo','codigo');
    copiar_columna('STG_CICLOS','nombre','est_ciclo','nombre');
    copiar_columna('STG_CICLOS','anio','est_ciclo','anio');
    copiar_columna('STG_CICLOS','fecha_inicio','est_ciclo','fecha_inicio');
    copiar_columna('STG_CICLOS','fecha_fin','est_ciclo','fecha_fin');
    copiar_columna('STG_CICLOS','estado','est_ciclo','estado');
    marcar_metadato('STG_CICLOS','id_ejecucion_carga');
    marcar_metadato('STG_CICLOS','fecha_carga');
    copiar_tabla('STG_PERIODOS','est_periodo_academico');
    copiar_columna('STG_PERIODOS','id_periodo','est_periodo_academico','id_periodo');
    copiar_columna('STG_PERIODOS','id_ciclo','est_periodo_academico','id_ciclo');
    copiar_columna('STG_PERIODOS','numero','est_periodo_academico','numero');
    copiar_columna('STG_PERIODOS','nombre','est_periodo_academico','nombre');
    copiar_columna('STG_PERIODOS','fecha_inicio','est_periodo_academico','fecha_inicio');
    copiar_columna('STG_PERIODOS','fecha_fin','est_periodo_academico','fecha_fin');
    marcar_metadato('STG_PERIODOS','id_ejecucion_carga');
    marcar_metadato('STG_PERIODOS','fecha_carga');
    copiar_tabla('STG_CURSOS','est_curso');
    copiar_columna('STG_CURSOS','id_curso','est_curso','id_curso');
    copiar_columna('STG_CURSOS','id_institucion','est_curso','id_institucion');
    copiar_columna('STG_CURSOS','id_ciclo','est_curso','id_ciclo');
    copiar_columna('STG_CURSOS','id_grado','est_curso','id_grado');
    copiar_columna('STG_CURSOS','id_jornada','est_curso','id_jornada');
    copiar_columna('STG_CURSOS','id_modalidad','est_curso','id_modalidad');
    copiar_columna('STG_CURSOS','codigo','est_curso','codigo');
    copiar_columna('STG_CURSOS','nombre','est_curso','nombre');
    copiar_columna('STG_CURSOS','seccion','est_curso','seccion');
    copiar_columna('STG_CURSOS','capacidad_maxima','est_curso','capacidad_maxima');
    copiar_columna('STG_CURSOS','estado','est_curso','estado');
    marcar_metadato('STG_CURSOS','id_ejecucion_carga');
    marcar_metadato('STG_CURSOS','fecha_carga');
    copiar_tabla('STG_CURSOS_ASIGNATURAS','est_curso_asignatura');
    copiar_columna('STG_CURSOS_ASIGNATURAS','id_curso_asignatura','est_curso_asignatura','id_curso_asignatura');
    copiar_columna('STG_CURSOS_ASIGNATURAS','id_curso','est_curso_asignatura','id_curso');
    copiar_columna('STG_CURSOS_ASIGNATURAS','id_asignatura','est_curso_asignatura','id_asignatura');
    copiar_columna('STG_CURSOS_ASIGNATURAS','horas_semanales','est_curso_asignatura','horas_semanales');
    copiar_columna('STG_CURSOS_ASIGNATURAS','creditos','est_curso_asignatura','creditos');
    copiar_columna('STG_CURSOS_ASIGNATURAS','tipo_resultado','est_curso_asignatura','tipo_resultado');
    copiar_columna('STG_CURSOS_ASIGNATURAS','regla_recuperacion','est_curso_asignatura','regla_recuperacion');
    copiar_columna('STG_CURSOS_ASIGNATURAS','estado','est_curso_asignatura','estado');
