    copiar_columna('STG_SESIONES','id_asignacion','trx_sesion_clase','id_asignacion');
    copiar_columna('STG_SESIONES','fecha_academica','trx_sesion_clase','fecha_academica');
    copiar_columna('STG_SESIONES','inicio','trx_sesion_clase','inicio');
    copiar_columna('STG_SESIONES','fin','trx_sesion_clase','fin');
    copiar_columna('STG_SESIONES','estado','trx_sesion_clase','estado');
    marcar_metadato('STG_SESIONES','id_ejecucion_carga');
