    copiar_tabla('STG_ASIGNACIONES_DOCENTES','trx_asignacion_docente');
    copiar_columna('STG_ASIGNACIONES_DOCENTES','id_asignacion','trx_asignacion_docente','id_asignacion');
    copiar_columna('STG_ASIGNACIONES_DOCENTES','id_docente','trx_asignacion_docente','id_docente');
    copiar_columna('STG_ASIGNACIONES_DOCENTES','id_curso_asignatura','trx_asignacion_docente','id_curso_asignatura');
    copiar_columna('STG_ASIGNACIONES_DOCENTES','fecha_asignacion','trx_asignacion_docente','fecha_asignacion');
    copiar_columna('STG_ASIGNACIONES_DOCENTES','fecha_inicio','trx_asignacion_docente','fecha_inicio');
    copiar_columna('STG_ASIGNACIONES_DOCENTES','fecha_fin','trx_asignacion_docente','fecha_fin');
    copiar_columna('STG_ASIGNACIONES_DOCENTES','estado','trx_asignacion_docente','estado');
    marcar_metadato('STG_ASIGNACIONES_DOCENTES','id_ejecucion_carga');
    marcar_metadato('STG_ASIGNACIONES_DOCENTES','fecha_carga');
    copiar_tabla('STG_INSTITUCIONES','mae_institucion');
