    comprobar_regla('OPERACION_TRX_CONTROL_CARGA_FK_periodo','trx_control_carga',q'~SELECT s.* FROM trx_control_carga s WHERE s.id_periodo IS NOT NULL AND NOT EXISTS (SELECT 1 FROM est_periodo_academico p WHERE p.id_periodo=s.id_periodo)~',q'~JSON_OBJECT('id_control' VALUE q.id_control,'id_curso' VALUE q.id_curso,'id_periodo' VALUE q.id_periodo,'dominio' VALUE q.dominio,'fecha_corte' VALUE q.fecha_corte,'estado' VALUE q.estado,'registros_declarados' VALUE q.registros_declarados,'fecha_recepcion' VALUE q.fecha_recepcion,'id_ejecucion' VALUE q.id_ejecucion RETURNING CLOB)~');
    comprobar_regla('OPERACION_TRX_CONTROL_CARGA_FK_ejecucion','trx_control_carga',q'~SELECT s.* FROM trx_control_carga s WHERE s.id_ejecucion IS NOT NULL AND NOT EXISTS (SELECT 1 FROM auditoria_etl_evaluaciones p WHERE p.id_ejecucion=s.id_ejecucion)~',q'~JSON_OBJECT('id_control' VALUE q.id_control,'id_curso' VALUE q.id_curso,'id_periodo' VALUE q.id_periodo,'dominio' VALUE q.dominio,'fecha_corte' VALUE q.fecha_corte,'estado' VALUE q.estado,'registros_declarados' VALUE q.registros_declarados,'fecha_recepcion' VALUE q.fecha_recepcion,'id_ejecucion' VALUE q.id_ejecucion RETURNING CLOB)~');
    comprobar_regla('OPERACION_PERIODO_CICLO','est_periodo_academico',q'~SELECT p.* FROM est_periodo_academico p JOIN est_ciclo c ON c.id_ciclo=p.id_ciclo WHERE (p.numero<1 OR p.numero<>TRUNC(p.numero)) OR p.fecha_inicio<c.fecha_inicio OR p.fecha_fin>c.fecha_fin OR p.fecha_fin<p.fecha_inicio~',q'~JSON_OBJECT('id_periodo' VALUE q.id_periodo,'id_ciclo' VALUE q.id_ciclo,'numero' VALUE q.numero,'nombre' VALUE q.nombre,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin RETURNING CLOB)~');
    comprobar_regla('OPERACION_PERIODOS_SOLAPADOS','est_periodo_academico',q'~SELECT p.* FROM est_periodo_academico p WHERE EXISTS (SELECT 1 FROM est_periodo_academico q WHERE q.id_ciclo=p.id_ciclo AND q.id_periodo<>p.id_periodo AND q.fecha_inicio<=p.fecha_fin AND p.fecha_inicio<=q.fecha_fin)~',q'~JSON_OBJECT('id_periodo' VALUE q.id_periodo,'id_ciclo' VALUE q.id_ciclo,'numero' VALUE q.numero,'nombre' VALUE q.nombre,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin RETURNING CLOB)~');
    comprobar_regla('OPERACION_PLAN_CICLO','est_ponderacion_periodo',q'~SELECT p.* FROM est_ponderacion_periodo p JOIN est_curso_asignatura a ON a.id_curso_asignatura=p.id_curso_asignatura JOIN est_curso c ON c.id_curso=a.id_curso JOIN est_periodo_academico x ON x.id_periodo=p.id_periodo WHERE c.id_ciclo<>x.id_ciclo~',q'~JSON_OBJECT('id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'id_curso_asignatura' VALUE q.id_curso_asignatura,'id_periodo' VALUE q.id_periodo,'peso' VALUE q.peso,'estado' VALUE q.estado RETURNING CLOB)~');
    comprobar_regla('OPERACION_PLAN_COMPLETO','est_ponderacion_periodo',q'~SELECT p.* FROM est_ponderacion_periodo p WHERE p.id_ponderacion_periodo IN (SELECT q.id_ponderacion_periodo FROM (SELECT w.id_ponderacion_periodo,w.id_curso_asignatura,COUNT(*) OVER (PARTITION BY w.id_curso_asignatura) AS publicados FROM est_ponderacion_periodo w WHERE w.estado='PUBLICADO') q LEFT JOIN est_curso_asignatura a ON a.id_curso_asignatura=q.id_curso_asignatura LEFT JOIN est_curso c ON c.id_curso=a.id_curso LEFT JOIN (SELECT id_ciclo,COUNT(*) AS periodos FROM est_periodo_academico GROUP BY id_ciclo) v ON v.id_ciclo=c.id_ciclo WHERE q.publicados<>COALESCE(v.periodos,0))~',q'~JSON_OBJECT('id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'id_curso_asignatura' VALUE q.id_curso_asignatura,'id_periodo' VALUE q.id_periodo,'peso' VALUE q.peso,'estado' VALUE q.estado RETURNING CLOB)~');
    comprobar_regla('OPERACION_PESOS_COMPARABLES','est_ponderacion_periodo',q'~SELECT p.* FROM est_ponderacion_periodo p WHERE p.id_ponderacion_periodo IN (SELECT x.id_ponderacion_periodo FROM (SELECT w.id_ponderacion_periodo,w.id_periodo,w.peso,SUM(w.peso) OVER (PARTITION BY w.id_curso_asignatura) AS total,c.id_ciclo,c.id_grado,a.id_asignatura FROM est_ponderacion_periodo w JOIN est_curso_asignatura a ON a.id_curso_asignatura=w.id_curso_asignatura JOIN est_curso c ON c.id_curso=a.id_curso WHERE w.estado='PUBLICADO') x JOIN (SELECT w.id_ponderacion_periodo,w.id_periodo,w.peso,SUM(w.peso) OVER (PARTITION BY w.id_curso_asignatura) AS total,c.id_ciclo,c.id_grado,a.id_asignatura FROM est_ponderacion_periodo w JOIN est_curso_asignatura a ON a.id_curso_asignatura=w.id_curso_asignatura JOIN est_curso c ON c.id_curso=a.id_curso WHERE w.estado='PUBLICADO') y ON y.id_periodo=x.id_periodo AND y.id_ciclo=x.id_ciclo AND y.id_grado=x.id_grado AND y.id_asignatura=x.id_asignatura WHERE ABS(x.peso*y.total-y.peso*x.total)>0.00000001)~',q'~JSON_OBJECT('id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'id_curso_asignatura' VALUE q.id_curso_asignatura,'id_periodo' VALUE q.id_periodo,'peso' VALUE q.peso,'estado' VALUE q.estado RETURNING CLOB)~');
    comprobar_regla('OPERACION_INSCRIPCION_CICLO','trx_inscripcion',q'~SELECT i.* FROM trx_inscripcion i JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE i.fecha_inicio<x.fecha_inicio OR i.fecha_inicio>x.fecha_fin OR (i.fecha_fin IS NOT NULL AND (i.fecha_fin<i.fecha_inicio OR i.fecha_fin>x.fecha_fin))~',q'~JSON_OBJECT('id_inscripcion' VALUE q.id_inscripcion,'id_estudiante' VALUE q.id_estudiante,'id_curso' VALUE q.id_curso,'fecha_inscripcion' VALUE q.fecha_inscripcion,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'estado' VALUE q.estado,'motivo_fin_inscripcion' VALUE q.motivo_fin_inscripcion,'resultado_cierre' VALUE q.resultado_cierre RETURNING CLOB)~');
    comprobar_regla('OPERACION_INSCRIPCIONES_SOLAPADAS','trx_inscripcion',q'~SELECT i.* FROM trx_inscripcion i WHERE i.id_inscripcion IN (SELECT w.id_inscripcion FROM (SELECT v.*,LAG(v.max_fin) OVER (PARTITION BY v.id_estudiante,v.id_ciclo ORDER BY v.fecha_inicio,v.id_inscripcion) AS fin_previo FROM (SELECT t.id_inscripcion,t.id_estudiante,c.id_ciclo,t.fecha_inicio,COALESCE(t.fecha_fin,x.fecha_fin) AS fin,MAX(COALESCE(t.fecha_fin,x.fecha_fin)) OVER (PARTITION BY t.id_estudiante,c.id_ciclo ORDER BY t.fecha_inicio,t.id_inscripcion ROWS UNBOUNDED PRECEDING) AS max_fin,LEAD(t.fecha_inicio) OVER (PARTITION BY t.id_estudiante,c.id_ciclo ORDER BY t.fecha_inicio,t.id_inscripcion) AS inicio_siguiente FROM trx_inscripcion t JOIN est_curso c ON c.id_curso=t.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE t.estado<>'ANULADA') v) w WHERE w.fin_previo>=w.fecha_inicio OR w.inicio_siguiente<=w.fin)~',q'~JSON_OBJECT('id_inscripcion' VALUE q.id_inscripcion,'id_estudiante' VALUE q.id_estudiante,'id_curso' VALUE q.id_curso,'fecha_inscripcion' VALUE q.fecha_inscripcion,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'estado' VALUE q.estado,'motivo_fin_inscripcion' VALUE q.motivo_fin_inscripcion,'resultado_cierre' VALUE q.resultado_cierre RETURNING CLOB)~');
    comprobar_regla('OPERACION_ASIGNACION_CICLO','trx_asignacion_docente',q'~SELECT a.* FROM trx_asignacion_docente a JOIN est_curso_asignatura o ON o.id_curso_asignatura=a.id_curso_asignatura JOIN est_curso c ON c.id_curso=o.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE a.fecha_inicio<x.fecha_inicio OR a.fecha_inicio>x.fecha_fin OR (a.fecha_fin IS NOT NULL AND (a.fecha_fin<a.fecha_inicio OR a.fecha_fin>x.fecha_fin))~',q'~JSON_OBJECT('id_asignacion' VALUE q.id_asignacion,'id_docente' VALUE q.id_docente,'id_curso_asignatura' VALUE q.id_curso_asignatura,'fecha_asignacion' VALUE q.fecha_asignacion,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'estado' VALUE q.estado RETURNING CLOB)~');
    comprobar_regla('OPERACION_ASIGNACIONES_SOLAPADAS','trx_asignacion_docente',q'~SELECT a.* FROM trx_asignacion_docente a JOIN est_curso_asignatura o ON o.id_curso_asignatura=a.id_curso_asignatura JOIN est_curso c ON c.id_curso=o.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE a.estado<>'ANULADA' AND EXISTS (SELECT 1 FROM trx_asignacion_docente b WHERE b.id_asignacion<>a.id_asignacion AND b.id_curso_asignatura=a.id_curso_asignatura AND b.estado<>'ANULADA' AND a.fecha_inicio<=COALESCE(b.fecha_fin,x.fecha_fin) AND b.fecha_inicio<=COALESCE(a.fecha_fin,x.fecha_fin))~',q'~JSON_OBJECT('id_asignacion' VALUE q.id_asignacion,'id_docente' VALUE q.id_docente,'id_curso_asignatura' VALUE q.id_curso_asignatura,'fecha_asignacion' VALUE q.fecha_asignacion,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'estado' VALUE q.estado RETURNING CLOB)~');
    comprobar_regla('OPERACION_PLAZO_CICLO','est_plazo_registro_notas',q'~SELECT w.* FROM est_plazo_registro_notas w JOIN est_periodo_academico p ON p.id_periodo=w.id_periodo WHERE w.id_ciclo<>p.id_ciclo~',q'~JSON_OBJECT('id_plazo_registro_notas' VALUE q.id_plazo_registro_notas,'id_institucion' VALUE q.id_institucion,'id_ciclo' VALUE q.id_ciclo,'id_grado' VALUE q.id_grado,'id_periodo' VALUE q.id_periodo,'tipo_intento' VALUE q.tipo_intento,'fecha_inicio_recuperacion' VALUE q.fecha_inicio_recuperacion,'fecha_fin_recuperacion' VALUE q.fecha_fin_recuperacion,'fecha_apertura_registro' VALUE q.fecha_apertura_registro,'fecha_limite_registro' VALUE q.fecha_limite_registro,'fecha_cierre_registro' VALUE q.fecha_cierre_registro,'estado' VALUE q.estado RETURNING CLOB)~');
    comprobar_regla('OPERACION_RECUPERACION_FECHAS','est_plazo_registro_notas',q'~SELECT w.* FROM est_plazo_registro_notas w WHERE (w.tipo_intento='ORDINARIA' AND (w.fecha_inicio_recuperacion IS NOT NULL OR w.fecha_fin_recuperacion IS NOT NULL)) OR (w.tipo_intento='RECUPERACION' AND (w.fecha_inicio_recuperacion IS NULL OR w.fecha_fin_recuperacion IS NULL OR w.fecha_fin_recuperacion<w.fecha_inicio_recuperacion))~',q'~JSON_OBJECT('id_plazo_registro_notas' VALUE q.id_plazo_registro_notas,'id_institucion' VALUE q.id_institucion,'id_ciclo' VALUE q.id_ciclo,'id_grado' VALUE q.id_grado,'id_periodo' VALUE q.id_periodo,'tipo_intento' VALUE q.tipo_intento,'fecha_inicio_recuperacion' VALUE q.fecha_inicio_recuperacion,'fecha_fin_recuperacion' VALUE q.fecha_fin_recuperacion,'fecha_apertura_registro' VALUE q.fecha_apertura_registro,'fecha_limite_registro' VALUE q.fecha_limite_registro,'fecha_cierre_registro' VALUE q.fecha_cierre_registro,'estado' VALUE q.estado RETURNING CLOB)~');
    comprobar_regla('OPERACION_CALIFICACION_CONTEXTO','trx_calificacion',q'~SELECT n.* FROM trx_calificacion n JOIN trx_inscripcion i ON i.id_inscripcion=n.id_inscripcion JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN est_curso_asignatura o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN trx_asignacion_docente a ON a.id_asignacion=n.id_asignacion_docente WHERE i.id_curso<>o.id_curso OR a.id_curso_asignatura<>o.id_curso_asignatura OR i.estado='ANULADA' OR a.estado='ANULADA' OR p.estado<>'PUBLICADO'~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion RETURNING CLOB)~');
    comprobar_regla('OPERACION_TIPO_RESULTADO','trx_calificacion',q'~SELECT n.* FROM trx_calificacion n JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN est_curso_asignatura o ON o.id_curso_asignatura=p.id_curso_asignatura WHERE (o.tipo_resultado='NUMERICA' AND (n.nota IS NULL OR n.resultado_cualitativo IS NOT NULL)) OR (o.tipo_resultado='CUALITATIVA' AND (n.nota IS NOT NULL OR n.resultado_cualitativo IS NULL))~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion RETURNING CLOB)~');
    comprobar_regla('OPERACION_ORDINARIA_VIGENCIA','trx_calificacion',q'~SELECT n.* FROM trx_calificacion n JOIN trx_inscripcion i ON i.id_inscripcion=n.id_inscripcion JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN est_periodo_academico x ON x.id_periodo=p.id_periodo JOIN trx_asignacion_docente a ON a.id_asignacion=n.id_asignacion_docente WHERE n.tipo_intento='ORDINARIA' AND (n.fecha_evaluacion<x.fecha_inicio OR n.fecha_evaluacion>x.fecha_fin OR n.fecha_evaluacion<i.fecha_inicio OR n.fecha_evaluacion>COALESCE(i.fecha_fin,x.fecha_fin) OR n.fecha_evaluacion<a.fecha_inicio OR n.fecha_evaluacion>COALESCE(a.fecha_fin,x.fecha_fin))~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion RETURNING CLOB)~');
    comprobar_regla('OPERACION_RECUPERACION_RESPONSABLE','trx_calificacion',q'~SELECT n.* FROM trx_calificacion n JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN est_periodo_academico x ON x.id_periodo=p.id_periodo JOIN trx_asignacion_docente a ON a.id_asignacion=n.id_asignacion_docente WHERE n.tipo_intento='RECUPERACION' AND (a.fecha_inicio>x.fecha_fin OR COALESCE(a.fecha_fin,x.fecha_fin)<x.fecha_inicio)~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion RETURNING CLOB)~');
    comprobar_regla('OPERACION_ORIGEN_RECUPERACION','trx_calificacion',q'~SELECT n.* FROM trx_calificacion n JOIN trx_calificacion b ON b.id_calificacion=n.id_calificacion_ordinaria WHERE n.tipo_intento='RECUPERACION' AND (b.tipo_intento<>'ORDINARIA' OR b.numero_intento<>1 OR b.id_inscripcion<>n.id_inscripcion OR b.id_ponderacion_periodo<>n.id_ponderacion_periodo OR b.fecha_evaluacion>n.fecha_evaluacion)~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion RETURNING CLOB)~');
    comprobar_regla('OPERACION_VERSION_ANTERIOR','trx_calificacion',q'~SELECT n.* FROM trx_calificacion n JOIN trx_calificacion b ON b.id_calificacion=n.id_calificacion_sustituida WHERE b.id_inscripcion<>n.id_inscripcion OR b.id_ponderacion_periodo<>n.id_ponderacion_periodo OR b.tipo_intento<>n.tipo_intento OR b.numero_intento<>n.numero_intento OR b.version+1<>n.version OR b.fecha_registro>n.fecha_registro~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion RETURNING CLOB)~');
    comprobar_regla('OPERACION_CAPTURA_AUTORIZADA','trx_calificacion',q'~SELECT n.* FROM trx_calificacion n JOIN trx_inscripcion i ON i.id_inscripcion=n.id_inscripcion JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo WHERE n.id_calificacion NOT IN (SELECT m.id_calificacion FROM trx_calificacion m JOIN trx_inscripcion j ON j.id_inscripcion=m.id_inscripcion JOIN est_curso d ON d.id_curso=j.id_curso JOIN est_ponderacion_periodo q ON q.id_ponderacion_periodo=m.id_ponderacion_periodo JOIN est_plazo_registro_notas w ON w.id_institucion=d.id_institucion AND w.id_ciclo=d.id_ciclo AND w.id_grado=d.id_grado AND w.id_periodo=q.id_periodo AND w.tipo_intento=m.tipo_intento WHERE m.fecha_registro>=w.fecha_apertura_registro AND (w.fecha_cierre_registro IS NULL OR m.fecha_registro<=w.fecha_cierre_registro) AND (m.tipo_intento='ORDINARIA' OR m.fecha_evaluacion BETWEEN w.fecha_inicio_recuperacion AND w.fecha_fin_recuperacion))~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion RETURNING CLOB)~');
    comprobar_regla('OPERACION_REGISTRO_NO_ANTICIPADO','trx_calificacion',q'~SELECT n.* FROM trx_calificacion n WHERE TRUNC(n.fecha_registro)<n.fecha_evaluacion~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion RETURNING CLOB)~');
    comprobar_regla('OPERACION_RESULTADO_CORRESPONDE','trx_resultado_periodo',q'~SELECT r.* FROM trx_resultado_periodo r JOIN trx_calificacion n ON n.id_calificacion=r.id_calificacion_seleccionada JOIN trx_inscripcion i ON i.id_inscripcion=n.id_inscripcion JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN est_curso_asignatura o ON o.id_curso_asignatura=p.id_curso_asignatura WHERE r.id_estudiante<>i.id_estudiante OR r.id_asignatura<>o.id_asignatura OR r.id_periodo<>p.id_periodo OR n.fecha_validacion IS NULL OR r.fecha_seleccion<n.fecha_validacion OR (r.fecha_cierre IS NOT NULL AND r.fecha_cierre<r.fecha_seleccion) OR (n.fecha_anulacion IS NOT NULL AND n.fecha_anulacion<=r.fecha_seleccion)~',q'~JSON_OBJECT('id_resultado' VALUE q.id_resultado,'id_estudiante' VALUE q.id_estudiante,'id_asignatura' VALUE q.id_asignatura,'id_periodo' VALUE q.id_periodo,'id_calificacion_seleccionada' VALUE q.id_calificacion_seleccionada,'version' VALUE q.version,'criterio' VALUE q.criterio,'fecha_seleccion' VALUE q.fecha_seleccion,'fecha_cierre' VALUE q.fecha_cierre RETURNING CLOB)~');
    comprobar_regla('OPERACION_SELECCION_VERSION_VIGENTE','trx_resultado_periodo',q'~SELECT r.* FROM trx_resultado_periodo r JOIN trx_calificacion n ON n.id_calificacion=r.id_calificacion_seleccionada WHERE EXISTS (SELECT 1 FROM trx_calificacion v WHERE v.id_inscripcion=n.id_inscripcion AND v.id_ponderacion_periodo=n.id_ponderacion_periodo AND v.tipo_intento=n.tipo_intento AND v.numero_intento=n.numero_intento AND v.version>n.version AND v.fecha_validacion<=r.fecha_seleccion)~',q'~JSON_OBJECT('id_resultado' VALUE q.id_resultado,'id_estudiante' VALUE q.id_estudiante,'id_asignatura' VALUE q.id_asignatura,'id_periodo' VALUE q.id_periodo,'id_calificacion_seleccionada' VALUE q.id_calificacion_seleccionada,'version' VALUE q.version,'criterio' VALUE q.criterio,'fecha_seleccion' VALUE q.fecha_seleccion,'fecha_cierre' VALUE q.fecha_cierre RETURNING CLOB)~');
    comprobar_regla('OPERACION_SELECCION_POLITICA','trx_resultado_periodo',q'~SELECT r.* FROM trx_resultado_periodo r WHERE r.id_resultado IN (SELECT x.id_resultado FROM trx_resultado_periodo x JOIN trx_calificacion n ON n.id_calificacion=x.id_calificacion_seleccionada JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN est_curso_asignatura o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN trx_calificacion m ON m.id_inscripcion=n.id_inscripcion AND m.id_ponderacion_periodo=n.id_ponderacion_periodo WHERE m.fecha_validacion<=x.fecha_seleccion AND (m.fecha_anulacion IS NULL OR m.fecha_anulacion>x.fecha_seleccion) AND ((o.regla_recuperacion='MEJOR_NOTA' AND o.tipo_resultado='NUMERICA' AND m.nota>n.nota) OR (o.regla_recuperacion='ULTIMA_RECUPERACION' AND m.numero_intento>n.numero_intento)) AND NOT EXISTS (SELECT 1 FROM trx_calificacion v WHERE v.id_inscripcion=m.id_inscripcion AND v.id_ponderacion_periodo=m.id_ponderacion_periodo AND v.tipo_intento=m.tipo_intento AND v.numero_intento=m.numero_intento AND v.version>m.version AND v.fecha_validacion<=x.fecha_seleccion))~',q'~JSON_OBJECT('id_resultado' VALUE q.id_resultado,'id_estudiante' VALUE q.id_estudiante,'id_asignatura' VALUE q.id_asignatura,'id_periodo' VALUE q.id_periodo,'id_calificacion_seleccionada' VALUE q.id_calificacion_seleccionada,'version' VALUE q.version,'criterio' VALUE q.criterio,'fecha_seleccion' VALUE q.fecha_seleccion,'fecha_cierre' VALUE q.fecha_cierre RETURNING CLOB)~');
    comprobar_regla('OPERACION_SESION_CONTEXTO','trx_sesion_clase',q'~SELECT s.* FROM trx_sesion_clase s JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=s.id_ponderacion_periodo JOIN est_periodo_academico x ON x.id_periodo=p.id_periodo JOIN trx_asignacion_docente a ON a.id_asignacion=s.id_asignacion WHERE p.id_curso_asignatura<>a.id_curso_asignatura OR s.fecha_academica<x.fecha_inicio OR s.fecha_academica>x.fecha_fin OR s.fecha_academica<a.fecha_inicio OR s.fecha_academica>COALESCE(a.fecha_fin,x.fecha_fin) OR s.fin<=s.inicio OR TRUNC(s.inicio)<>s.fecha_academica OR a.estado='ANULADA'~',q'~JSON_OBJECT('id_sesion' VALUE q.id_sesion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'id_asignacion' VALUE q.id_asignacion,'fecha_academica' VALUE q.fecha_academica,'inicio' VALUE q.inicio,'fin' VALUE q.fin,'estado' VALUE q.estado,'observaciones' VALUE q.observaciones RETURNING CLOB)~');
    comprobar_regla('OPERACION_SESIONES_SIMULTANEAS','trx_sesion_clase',q'~SELECT s.* FROM trx_sesion_clase s WHERE s.id_sesion IN (SELECT id_sesion FROM (SELECT v.*,LAG(v.max_hasta) OVER (PARTITION BY v.k ORDER BY v.inicio,v.id_sesion) AS fin_previo FROM (SELECT t.id_sesion,t.inicio,t.fin,b.id_docente AS k,MAX(t.fin) OVER (PARTITION BY b.id_docente ORDER BY t.inicio,t.id_sesion ROWS UNBOUNDED PRECEDING) AS max_hasta,LEAD(t.inicio) OVER (PARTITION BY b.id_docente ORDER BY t.inicio,t.id_sesion) AS inicio_siguiente FROM trx_sesion_clase t JOIN trx_asignacion_docente b ON b.id_asignacion=t.id_asignacion WHERE t.estado<>'CANCELADA') v) w WHERE w.fin_previo>w.inicio OR w.inicio_siguiente<w.fin UNION SELECT id_sesion FROM (SELECT v.*,LAG(v.max_hasta) OVER (PARTITION BY v.k ORDER BY v.inicio,v.id_sesion) AS fin_previo FROM (SELECT t.id_sesion,t.inicio,t.fin,z.id_curso AS k,MAX(t.fin) OVER (PARTITION BY z.id_curso ORDER BY t.inicio,t.id_sesion ROWS UNBOUNDED PRECEDING) AS max_hasta,LEAD(t.inicio) OVER (PARTITION BY z.id_curso ORDER BY t.inicio,t.id_sesion) AS inicio_siguiente FROM trx_sesion_clase t JOIN est_ponderacion_periodo q ON q.id_ponderacion_periodo=t.id_ponderacion_periodo JOIN est_curso_asignatura z ON z.id_curso_asignatura=q.id_curso_asignatura WHERE t.estado<>'CANCELADA') v) w WHERE w.fin_previo>w.inicio OR w.inicio_siguiente<w.fin)~',q'~JSON_OBJECT('id_sesion' VALUE q.id_sesion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'id_asignacion' VALUE q.id_asignacion,'fecha_academica' VALUE q.fecha_academica,'inicio' VALUE q.inicio,'fin' VALUE q.fin,'estado' VALUE q.estado,'observaciones' VALUE q.observaciones RETURNING CLOB)~');
    comprobar_regla('OPERACION_ASISTENCIA_CONTEXTO','trx_asistencia',q'~SELECT a.* FROM trx_asistencia a JOIN trx_inscripcion i ON i.id_inscripcion=a.id_inscripcion JOIN trx_sesion_clase s ON s.id_sesion=a.id_sesion JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=s.id_ponderacion_periodo JOIN est_curso_asignatura o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE i.id_curso<>o.id_curso OR i.estado='ANULADA' OR s.estado<>'IMPARTIDA' OR s.fecha_academica<i.fecha_inicio OR s.fecha_academica>COALESCE(i.fecha_fin,x.fecha_fin) OR a.fecha_registro<s.fin OR (a.estado IN ('AUSENTE','JUSTIFICADA') AND a.hora_llegada IS NOT NULL)~',q'~JSON_OBJECT('id_asistencia' VALUE q.id_asistencia,'id_inscripcion' VALUE q.id_inscripcion,'id_sesion' VALUE q.id_sesion,'estado' VALUE q.estado,'hora_llegada' VALUE q.hora_llegada,'fecha_registro' VALUE q.fecha_registro,'observaciones' VALUE q.observaciones RETURNING CLOB)~');
    comprobar_regla('OPERACION_BECA_HABILITADA','trx_beca',q'~SELECT b.* FROM trx_beca b JOIN trx_inscripcion i ON i.id_inscripcion=b.id_inscripcion JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_institucion_ciclo h ON h.id_institucion=c.id_institucion AND h.id_ciclo=c.id_ciclo WHERE h.permite_becas<>1 OR i.estado='ANULADA'~',q'~JSON_OBJECT('id_beca' VALUE q.id_beca,'id_inscripcion' VALUE q.id_inscripcion,'id_tipo_beca' VALUE q.id_tipo_beca,'porcentaje' VALUE q.porcentaje,'fecha_otorgamiento' VALUE q.fecha_otorgamiento,'fecha_registro' VALUE q.fecha_registro,'observaciones' VALUE q.observaciones RETURNING CLOB)~');
    comprobar_regla('OPERACION_BECA_VIGENCIA','trx_beca_vigencia',q'~SELECT v.* FROM trx_beca_vigencia v JOIN trx_beca b ON b.id_beca=v.id_beca JOIN trx_inscripcion i ON i.id_inscripcion=b.id_inscripcion JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE v.fecha_inicio<i.fecha_inicio OR v.fecha_inicio>COALESCE(i.fecha_fin,x.fecha_fin) OR (v.fecha_fin IS NOT NULL AND (v.fecha_fin<v.fecha_inicio OR v.fecha_fin>COALESCE(i.fecha_fin,x.fecha_fin))) OR (v.fecha_fin IS NULL AND v.motivo_fin IS NOT NULL) OR (v.fecha_fin IS NOT NULL AND v.motivo_fin IS NULL)~',q'~JSON_OBJECT('id_vigencia' VALUE q.id_vigencia,'id_beca' VALUE q.id_beca,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'motivo_fin' VALUE q.motivo_fin,'fecha_registro' VALUE q.fecha_registro RETURNING CLOB)~');
    comprobar_regla('OPERACION_BECA_SOLAPADA','trx_beca_vigencia',q'~SELECT v.* FROM trx_beca_vigencia v JOIN trx_beca b ON b.id_beca=v.id_beca JOIN trx_inscripcion i ON i.id_inscripcion=b.id_inscripcion JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE EXISTS (SELECT 1 FROM trx_beca_vigencia w WHERE w.id_beca=v.id_beca AND w.id_vigencia<>v.id_vigencia AND v.fecha_inicio<=COALESCE(w.fecha_fin,x.fecha_fin) AND w.fecha_inicio<=COALESCE(v.fecha_fin,x.fecha_fin))~',q'~JSON_OBJECT('id_vigencia' VALUE q.id_vigencia,'id_beca' VALUE q.id_beca,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'motivo_fin' VALUE q.motivo_fin,'fecha_registro' VALUE q.fecha_registro RETURNING CLOB)~');
    comprobar_regla('OPERACION_PORCENTAJE_SIMULTANEO','trx_beca_vigencia',q'~SELECT v.* FROM trx_beca_vigencia v JOIN trx_beca b ON b.id_beca=v.id_beca JOIN trx_inscripcion i ON i.id_inscripcion=b.id_inscripcion JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE (SELECT SUM(z.porcentaje) FROM trx_beca_vigencia w JOIN trx_beca z ON z.id_beca=w.id_beca WHERE z.id_inscripcion=b.id_inscripcion AND w.fecha_inicio<=v.fecha_inicio AND COALESCE(w.fecha_fin,x.fecha_fin)>=v.fecha_inicio)>100~',q'~JSON_OBJECT('id_vigencia' VALUE q.id_vigencia,'id_beca' VALUE q.id_beca,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'motivo_fin' VALUE q.motivo_fin,'fecha_registro' VALUE q.fecha_registro RETURNING CLOB)~');
