    comprobar_regla('STAGING_PERIODO_CICLO','STG_PERIODOS',q'~SELECT p.* FROM STG_PERIODOS p JOIN STG_CICLOS c ON c.id_ciclo=p.id_ciclo WHERE (p.numero<1 OR p.numero<>TRUNC(p.numero)) OR p.fecha_inicio<c.fecha_inicio OR p.fecha_fin>c.fecha_fin OR p.fecha_fin<p.fecha_inicio~',q'~JSON_OBJECT('id_periodo' VALUE q.id_periodo,'id_ciclo' VALUE q.id_ciclo,'numero' VALUE q.numero,'nombre' VALUE q.nombre,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_PERIODOS_SOLAPADOS','STG_PERIODOS',q'~SELECT p.* FROM STG_PERIODOS p WHERE EXISTS (SELECT 1 FROM STG_PERIODOS q WHERE q.id_ciclo=p.id_ciclo AND q.id_periodo<>p.id_periodo AND q.fecha_inicio<=p.fecha_fin AND p.fecha_inicio<=q.fecha_fin)~',q'~JSON_OBJECT('id_periodo' VALUE q.id_periodo,'id_ciclo' VALUE q.id_ciclo,'numero' VALUE q.numero,'nombre' VALUE q.nombre,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_PLAN_CICLO','STG_PONDERACIONES',q'~SELECT p.* FROM STG_PONDERACIONES p JOIN STG_CURSOS_ASIGNATURAS a ON a.id_curso_asignatura=p.id_curso_asignatura JOIN STG_CURSOS c ON c.id_curso=a.id_curso JOIN STG_PERIODOS x ON x.id_periodo=p.id_periodo WHERE c.id_ciclo<>x.id_ciclo~',q'~JSON_OBJECT('id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'id_curso_asignatura' VALUE q.id_curso_asignatura,'id_periodo' VALUE q.id_periodo,'peso' VALUE q.peso,'estado' VALUE q.estado,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_PLAN_COMPLETO','STG_PONDERACIONES',q'~SELECT p.* FROM STG_PONDERACIONES p WHERE p.id_ponderacion_periodo IN (SELECT q.id_ponderacion_periodo FROM (SELECT w.id_ponderacion_periodo,w.id_curso_asignatura,COUNT(*) OVER (PARTITION BY w.id_curso_asignatura) AS publicados FROM STG_PONDERACIONES w WHERE w.estado='PUBLICADO') q LEFT JOIN STG_CURSOS_ASIGNATURAS a ON a.id_curso_asignatura=q.id_curso_asignatura LEFT JOIN STG_CURSOS c ON c.id_curso=a.id_curso LEFT JOIN (SELECT id_ciclo,COUNT(*) AS periodos FROM STG_PERIODOS GROUP BY id_ciclo) v ON v.id_ciclo=c.id_ciclo WHERE q.publicados<>COALESCE(v.periodos,0))~',q'~JSON_OBJECT('id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'id_curso_asignatura' VALUE q.id_curso_asignatura,'id_periodo' VALUE q.id_periodo,'peso' VALUE q.peso,'estado' VALUE q.estado,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_PESOS_COMPARABLES','STG_PONDERACIONES',q'~SELECT p.* FROM STG_PONDERACIONES p WHERE p.id_ponderacion_periodo IN (SELECT x.id_ponderacion_periodo FROM (SELECT w.id_ponderacion_periodo,w.id_periodo,w.peso,SUM(w.peso) OVER (PARTITION BY w.id_curso_asignatura) AS total,c.id_ciclo,c.id_grado,a.id_asignatura FROM STG_PONDERACIONES w JOIN STG_CURSOS_ASIGNATURAS a ON a.id_curso_asignatura=w.id_curso_asignatura JOIN STG_CURSOS c ON c.id_curso=a.id_curso WHERE w.estado='PUBLICADO') x JOIN (SELECT w.id_ponderacion_periodo,w.id_periodo,w.peso,SUM(w.peso) OVER (PARTITION BY w.id_curso_asignatura) AS total,c.id_ciclo,c.id_grado,a.id_asignatura FROM STG_PONDERACIONES w JOIN STG_CURSOS_ASIGNATURAS a ON a.id_curso_asignatura=w.id_curso_asignatura JOIN STG_CURSOS c ON c.id_curso=a.id_curso WHERE w.estado='PUBLICADO') y ON y.id_periodo=x.id_periodo AND y.id_ciclo=x.id_ciclo AND y.id_grado=x.id_grado AND y.id_asignatura=x.id_asignatura WHERE ABS(x.peso*y.total-y.peso*x.total)>0.00000001)~',q'~JSON_OBJECT('id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'id_curso_asignatura' VALUE q.id_curso_asignatura,'id_periodo' VALUE q.id_periodo,'peso' VALUE q.peso,'estado' VALUE q.estado,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_INSCRIPCION_CICLO','STG_INSCRIPCIONES',q'~SELECT i.* FROM STG_INSCRIPCIONES i JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE i.fecha_inicio<x.fecha_inicio OR i.fecha_inicio>x.fecha_fin OR (i.fecha_fin IS NOT NULL AND (i.fecha_fin<i.fecha_inicio OR i.fecha_fin>x.fecha_fin))~',q'~JSON_OBJECT('id_inscripcion' VALUE q.id_inscripcion,'id_estudiante' VALUE q.id_estudiante,'id_curso' VALUE q.id_curso,'fecha_inscripcion' VALUE q.fecha_inscripcion,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'estado' VALUE q.estado,'motivo_fin_inscripcion' VALUE q.motivo_fin_inscripcion,'resultado_cierre' VALUE q.resultado_cierre,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_INSCRIPCIONES_SOLAPADAS','STG_INSCRIPCIONES',q'~SELECT i.* FROM STG_INSCRIPCIONES i WHERE i.id_inscripcion IN (SELECT w.id_inscripcion FROM (SELECT v.*,LAG(v.max_fin) OVER (PARTITION BY v.id_estudiante,v.id_ciclo ORDER BY v.fecha_inicio,v.id_inscripcion) AS fin_previo FROM (SELECT t.id_inscripcion,t.id_estudiante,c.id_ciclo,t.fecha_inicio,COALESCE(t.fecha_fin,x.fecha_fin) AS fin,MAX(COALESCE(t.fecha_fin,x.fecha_fin)) OVER (PARTITION BY t.id_estudiante,c.id_ciclo ORDER BY t.fecha_inicio,t.id_inscripcion ROWS UNBOUNDED PRECEDING) AS max_fin,LEAD(t.fecha_inicio) OVER (PARTITION BY t.id_estudiante,c.id_ciclo ORDER BY t.fecha_inicio,t.id_inscripcion) AS inicio_siguiente FROM STG_INSCRIPCIONES t JOIN STG_CURSOS c ON c.id_curso=t.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE t.estado<>'ANULADA') v) w WHERE w.fin_previo>=w.fecha_inicio OR w.inicio_siguiente<=w.fin)~',q'~JSON_OBJECT('id_inscripcion' VALUE q.id_inscripcion,'id_estudiante' VALUE q.id_estudiante,'id_curso' VALUE q.id_curso,'fecha_inscripcion' VALUE q.fecha_inscripcion,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'estado' VALUE q.estado,'motivo_fin_inscripcion' VALUE q.motivo_fin_inscripcion,'resultado_cierre' VALUE q.resultado_cierre,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_ASIGNACION_CICLO','STG_ASIGNACIONES_DOCENTES',q'~SELECT a.* FROM STG_ASIGNACIONES_DOCENTES a JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=a.id_curso_asignatura JOIN STG_CURSOS c ON c.id_curso=o.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE a.fecha_inicio<x.fecha_inicio OR a.fecha_inicio>x.fecha_fin OR (a.fecha_fin IS NOT NULL AND (a.fecha_fin<a.fecha_inicio OR a.fecha_fin>x.fecha_fin))~',q'~JSON_OBJECT('id_asignacion' VALUE q.id_asignacion,'id_docente' VALUE q.id_docente,'id_curso_asignatura' VALUE q.id_curso_asignatura,'fecha_asignacion' VALUE q.fecha_asignacion,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'estado' VALUE q.estado,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_ASIGNACIONES_SOLAPADAS','STG_ASIGNACIONES_DOCENTES',q'~SELECT a.* FROM STG_ASIGNACIONES_DOCENTES a JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=a.id_curso_asignatura JOIN STG_CURSOS c ON c.id_curso=o.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE a.estado<>'ANULADA' AND EXISTS (SELECT 1 FROM STG_ASIGNACIONES_DOCENTES b WHERE b.id_asignacion<>a.id_asignacion AND b.id_curso_asignatura=a.id_curso_asignatura AND b.estado<>'ANULADA' AND a.fecha_inicio<=COALESCE(b.fecha_fin,x.fecha_fin) AND b.fecha_inicio<=COALESCE(a.fecha_fin,x.fecha_fin))~',q'~JSON_OBJECT('id_asignacion' VALUE q.id_asignacion,'id_docente' VALUE q.id_docente,'id_curso_asignatura' VALUE q.id_curso_asignatura,'fecha_asignacion' VALUE q.fecha_asignacion,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'estado' VALUE q.estado,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
