    comprobar_regla('STAGING_RECUPERACION_FECHAS','STG_PLAZOS_NOTAS',q'~SELECT w.* FROM STG_PLAZOS_NOTAS w WHERE (w.tipo_intento='ORDINARIA' AND (w.fecha_inicio_recuperacion IS NOT NULL OR w.fecha_fin_recuperacion IS NOT NULL)) OR (w.tipo_intento='RECUPERACION' AND (w.fecha_inicio_recuperacion IS NULL OR w.fecha_fin_recuperacion IS NULL OR w.fecha_fin_recuperacion<w.fecha_inicio_recuperacion))~',q'~JSON_OBJECT('id_plazo_registro_notas' VALUE q.id_plazo_registro_notas,'id_institucion' VALUE q.id_institucion,'id_ciclo' VALUE q.id_ciclo,'id_grado' VALUE q.id_grado,'id_periodo' VALUE q.id_periodo,'tipo_intento' VALUE q.tipo_intento,'fecha_inicio_recuperacion' VALUE q.fecha_inicio_recuperacion,'fecha_fin_recuperacion' VALUE q.fecha_fin_recuperacion,'fecha_apertura_registro' VALUE q.fecha_apertura_registro,'fecha_limite_registro' VALUE q.fecha_limite_registro,'fecha_cierre_registro' VALUE q.fecha_cierre_registro,'estado' VALUE q.estado,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_CALIFICACION_CONTEXTO','STG_CALIFICACIONES',q'~SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=n.id_inscripcion JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN STG_ASIGNACIONES_DOCENTES a ON a.id_asignacion=n.id_asignacion_docente WHERE i.id_curso<>o.id_curso OR a.id_curso_asignatura<>o.id_curso_asignatura OR i.estado='ANULADA' OR a.estado='ANULADA' OR p.estado<>'PUBLICADO'~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_TIPO_RESULTADO','STG_CALIFICACIONES',q'~SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=p.id_curso_asignatura WHERE (o.tipo_resultado='NUMERICA' AND (n.nota IS NULL OR n.resultado_cualitativo IS NOT NULL)) OR (o.tipo_resultado='CUALITATIVA' AND (n.nota IS NOT NULL OR n.resultado_cualitativo IS NULL))~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_ORDINARIA_VIGENCIA','STG_CALIFICACIONES',q'~SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=n.id_inscripcion JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN STG_PERIODOS x ON x.id_periodo=p.id_periodo JOIN STG_ASIGNACIONES_DOCENTES a ON a.id_asignacion=n.id_asignacion_docente WHERE n.tipo_intento='ORDINARIA' AND (n.fecha_evaluacion<x.fecha_inicio OR n.fecha_evaluacion>x.fecha_fin OR n.fecha_evaluacion<i.fecha_inicio OR n.fecha_evaluacion>COALESCE(i.fecha_fin,x.fecha_fin) OR n.fecha_evaluacion<a.fecha_inicio OR n.fecha_evaluacion>COALESCE(a.fecha_fin,x.fecha_fin))~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_RECUPERACION_RESPONSABLE','STG_CALIFICACIONES',q'~SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN STG_PERIODOS x ON x.id_periodo=p.id_periodo JOIN STG_ASIGNACIONES_DOCENTES a ON a.id_asignacion=n.id_asignacion_docente WHERE n.tipo_intento='RECUPERACION' AND (a.fecha_inicio>x.fecha_fin OR COALESCE(a.fecha_fin,x.fecha_fin)<x.fecha_inicio)~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_ORIGEN_RECUPERACION','STG_CALIFICACIONES',q'~SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_CALIFICACIONES b ON b.id_calificacion=n.id_calificacion_ordinaria WHERE n.tipo_intento='RECUPERACION' AND (b.tipo_intento<>'ORDINARIA' OR b.numero_intento<>1 OR b.id_inscripcion<>n.id_inscripcion OR b.id_ponderacion_periodo<>n.id_ponderacion_periodo OR b.fecha_evaluacion>n.fecha_evaluacion)~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_VERSION_ANTERIOR','STG_CALIFICACIONES',q'~SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_CALIFICACIONES b ON b.id_calificacion=n.id_calificacion_sustituida WHERE b.id_inscripcion<>n.id_inscripcion OR b.id_ponderacion_periodo<>n.id_ponderacion_periodo OR b.tipo_intento<>n.tipo_intento OR b.numero_intento<>n.numero_intento OR b.version+1<>n.version OR b.fecha_registro>n.fecha_registro~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_CAPTURA_AUTORIZADA','STG_CALIFICACIONES',q'~SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=n.id_inscripcion JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo WHERE n.id_calificacion NOT IN (SELECT m.id_calificacion FROM STG_CALIFICACIONES m JOIN STG_INSCRIPCIONES j ON j.id_inscripcion=m.id_inscripcion JOIN STG_CURSOS d ON d.id_curso=j.id_curso JOIN STG_PONDERACIONES q ON q.id_ponderacion_periodo=m.id_ponderacion_periodo JOIN STG_PLAZOS_NOTAS w ON w.id_institucion=d.id_institucion AND w.id_ciclo=d.id_ciclo AND w.id_grado=d.id_grado AND w.id_periodo=q.id_periodo AND w.tipo_intento=m.tipo_intento WHERE m.fecha_registro>=w.fecha_apertura_registro AND (w.fecha_cierre_registro IS NULL OR m.fecha_registro<=w.fecha_cierre_registro) AND (m.tipo_intento='ORDINARIA' OR m.fecha_evaluacion BETWEEN w.fecha_inicio_recuperacion AND w.fecha_fin_recuperacion))~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_REGISTRO_NO_ANTICIPADO','STG_CALIFICACIONES',q'~SELECT n.* FROM STG_CALIFICACIONES n WHERE TRUNC(n.fecha_registro)<n.fecha_evaluacion~',q'~JSON_OBJECT('id_calificacion' VALUE q.id_calificacion,'id_inscripcion' VALUE q.id_inscripcion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'tipo_intento' VALUE q.tipo_intento,'numero_intento' VALUE q.numero_intento,'version' VALUE q.version,'id_calificacion_ordinaria' VALUE q.id_calificacion_ordinaria,'id_calificacion_sustituida' VALUE q.id_calificacion_sustituida,'id_asignacion_docente' VALUE q.id_asignacion_docente,'id_docente_registra' VALUE q.id_docente_registra,'nota' VALUE q.nota,'resultado_cualitativo' VALUE q.resultado_cualitativo,'fecha_evaluacion' VALUE q.fecha_evaluacion,'fecha_registro' VALUE q.fecha_registro,'fecha_validacion' VALUE q.fecha_validacion,'fecha_anulacion' VALUE q.fecha_anulacion,'motivo_anulacion' VALUE q.motivo_anulacion,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_RESULTADO_CORRESPONDE','STG_RESULTADOS_PERIODO',q'~SELECT r.* FROM STG_RESULTADOS_PERIODO r JOIN STG_CALIFICACIONES n ON n.id_calificacion=r.id_calificacion_seleccionada JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=n.id_inscripcion JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=p.id_curso_asignatura WHERE r.id_estudiante<>i.id_estudiante OR r.id_asignatura<>o.id_asignatura OR r.id_periodo<>p.id_periodo OR n.fecha_validacion IS NULL OR r.fecha_seleccion<n.fecha_validacion OR (r.fecha_cierre IS NOT NULL AND r.fecha_cierre<r.fecha_seleccion) OR (n.fecha_anulacion IS NOT NULL AND n.fecha_anulacion<=r.fecha_seleccion)~',q'~JSON_OBJECT('id_resultado' VALUE q.id_resultado,'id_estudiante' VALUE q.id_estudiante,'id_asignatura' VALUE q.id_asignatura,'id_periodo' VALUE q.id_periodo,'id_calificacion_seleccionada' VALUE q.id_calificacion_seleccionada,'version' VALUE q.version,'criterio' VALUE q.criterio,'fecha_seleccion' VALUE q.fecha_seleccion,'fecha_cierre' VALUE q.fecha_cierre,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_SELECCION_VERSION_VIGENTE','STG_RESULTADOS_PERIODO',q'~SELECT r.* FROM STG_RESULTADOS_PERIODO r JOIN STG_CALIFICACIONES n ON n.id_calificacion=r.id_calificacion_seleccionada WHERE EXISTS (SELECT 1 FROM STG_CALIFICACIONES v WHERE v.id_inscripcion=n.id_inscripcion AND v.id_ponderacion_periodo=n.id_ponderacion_periodo AND v.tipo_intento=n.tipo_intento AND v.numero_intento=n.numero_intento AND v.version>n.version AND v.fecha_validacion<=r.fecha_seleccion)~',q'~JSON_OBJECT('id_resultado' VALUE q.id_resultado,'id_estudiante' VALUE q.id_estudiante,'id_asignatura' VALUE q.id_asignatura,'id_periodo' VALUE q.id_periodo,'id_calificacion_seleccionada' VALUE q.id_calificacion_seleccionada,'version' VALUE q.version,'criterio' VALUE q.criterio,'fecha_seleccion' VALUE q.fecha_seleccion,'fecha_cierre' VALUE q.fecha_cierre,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_SELECCION_POLITICA','STG_RESULTADOS_PERIODO',q'~SELECT r.* FROM STG_RESULTADOS_PERIODO r WHERE r.id_resultado IN (SELECT x.id_resultado FROM STG_RESULTADOS_PERIODO x JOIN STG_CALIFICACIONES n ON n.id_calificacion=x.id_calificacion_seleccionada JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN STG_CALIFICACIONES m ON m.id_inscripcion=n.id_inscripcion AND m.id_ponderacion_periodo=n.id_ponderacion_periodo WHERE m.fecha_validacion<=x.fecha_seleccion AND (m.fecha_anulacion IS NULL OR m.fecha_anulacion>x.fecha_seleccion) AND ((o.regla_recuperacion='MEJOR_NOTA' AND o.tipo_resultado='NUMERICA' AND m.nota>n.nota) OR (o.regla_recuperacion='ULTIMA_RECUPERACION' AND m.numero_intento>n.numero_intento)) AND NOT EXISTS (SELECT 1 FROM STG_CALIFICACIONES v WHERE v.id_inscripcion=m.id_inscripcion AND v.id_ponderacion_periodo=m.id_ponderacion_periodo AND v.tipo_intento=m.tipo_intento AND v.numero_intento=m.numero_intento AND v.version>m.version AND v.fecha_validacion<=x.fecha_seleccion))~',q'~JSON_OBJECT('id_resultado' VALUE q.id_resultado,'id_estudiante' VALUE q.id_estudiante,'id_asignatura' VALUE q.id_asignatura,'id_periodo' VALUE q.id_periodo,'id_calificacion_seleccionada' VALUE q.id_calificacion_seleccionada,'version' VALUE q.version,'criterio' VALUE q.criterio,'fecha_seleccion' VALUE q.fecha_seleccion,'fecha_cierre' VALUE q.fecha_cierre,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_SESION_CONTEXTO','STG_SESIONES',q'~SELECT s.* FROM STG_SESIONES s JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=s.id_ponderacion_periodo JOIN STG_PERIODOS x ON x.id_periodo=p.id_periodo JOIN STG_ASIGNACIONES_DOCENTES a ON a.id_asignacion=s.id_asignacion WHERE p.id_curso_asignatura<>a.id_curso_asignatura OR s.fecha_academica<x.fecha_inicio OR s.fecha_academica>x.fecha_fin OR s.fecha_academica<a.fecha_inicio OR s.fecha_academica>COALESCE(a.fecha_fin,x.fecha_fin) OR s.fin<=s.inicio OR TRUNC(s.inicio)<>s.fecha_academica OR a.estado='ANULADA'~',q'~JSON_OBJECT('id_sesion' VALUE q.id_sesion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'id_asignacion' VALUE q.id_asignacion,'fecha_academica' VALUE q.fecha_academica,'inicio' VALUE q.inicio,'fin' VALUE q.fin,'estado' VALUE q.estado,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_SESIONES_SIMULTANEAS','STG_SESIONES',q'~SELECT s.* FROM STG_SESIONES s WHERE s.id_sesion IN (SELECT id_sesion FROM (SELECT v.*,LAG(v.max_hasta) OVER (PARTITION BY v.k ORDER BY v.inicio,v.id_sesion) AS fin_previo FROM (SELECT t.id_sesion,t.inicio,t.fin,b.id_docente AS k,MAX(t.fin) OVER (PARTITION BY b.id_docente ORDER BY t.inicio,t.id_sesion ROWS UNBOUNDED PRECEDING) AS max_hasta,LEAD(t.inicio) OVER (PARTITION BY b.id_docente ORDER BY t.inicio,t.id_sesion) AS inicio_siguiente FROM STG_SESIONES t JOIN STG_ASIGNACIONES_DOCENTES b ON b.id_asignacion=t.id_asignacion WHERE t.estado<>'CANCELADA') v) w WHERE w.fin_previo>w.inicio OR w.inicio_siguiente<w.fin UNION SELECT id_sesion FROM (SELECT v.*,LAG(v.max_hasta) OVER (PARTITION BY v.k ORDER BY v.inicio,v.id_sesion) AS fin_previo FROM (SELECT t.id_sesion,t.inicio,t.fin,z.id_curso AS k,MAX(t.fin) OVER (PARTITION BY z.id_curso ORDER BY t.inicio,t.id_sesion ROWS UNBOUNDED PRECEDING) AS max_hasta,LEAD(t.inicio) OVER (PARTITION BY z.id_curso ORDER BY t.inicio,t.id_sesion) AS inicio_siguiente FROM STG_SESIONES t JOIN STG_PONDERACIONES q ON q.id_ponderacion_periodo=t.id_ponderacion_periodo JOIN STG_CURSOS_ASIGNATURAS z ON z.id_curso_asignatura=q.id_curso_asignatura WHERE t.estado<>'CANCELADA') v) w WHERE w.fin_previo>w.inicio OR w.inicio_siguiente<w.fin)~',q'~JSON_OBJECT('id_sesion' VALUE q.id_sesion,'id_ponderacion_periodo' VALUE q.id_ponderacion_periodo,'id_asignacion' VALUE q.id_asignacion,'fecha_academica' VALUE q.fecha_academica,'inicio' VALUE q.inicio,'fin' VALUE q.fin,'estado' VALUE q.estado,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_ASISTENCIA_CONTEXTO','STG_ASISTENCIAS',q'~SELECT a.* FROM STG_ASISTENCIAS a JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=a.id_inscripcion JOIN STG_SESIONES s ON s.id_sesion=a.id_sesion JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=s.id_ponderacion_periodo JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE i.id_curso<>o.id_curso OR i.estado='ANULADA' OR s.estado<>'IMPARTIDA' OR s.fecha_academica<i.fecha_inicio OR s.fecha_academica>COALESCE(i.fecha_fin,x.fecha_fin) OR a.fecha_registro<s.fin OR (a.estado IN ('AUSENTE','JUSTIFICADA') AND a.hora_llegada IS NOT NULL)~',q'~JSON_OBJECT('id_asistencia' VALUE q.id_asistencia,'id_inscripcion' VALUE q.id_inscripcion,'id_sesion' VALUE q.id_sesion,'estado' VALUE q.estado,'hora_llegada' VALUE q.hora_llegada,'fecha_registro' VALUE q.fecha_registro,'observaciones' VALUE q.observaciones,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_BECA_HABILITADA','STG_BECAS',q'~SELECT b.* FROM STG_BECAS b JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=b.id_inscripcion JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_INSTITUCIONES_CICLO h ON h.id_institucion=c.id_institucion AND h.id_ciclo=c.id_ciclo WHERE h.permite_becas<>1 OR i.estado='ANULADA'~',q'~JSON_OBJECT('id_beca' VALUE q.id_beca,'id_inscripcion' VALUE q.id_inscripcion,'id_tipo_beca' VALUE q.id_tipo_beca,'porcentaje' VALUE q.porcentaje,'fecha_otorgamiento' VALUE q.fecha_otorgamiento,'fecha_registro' VALUE q.fecha_registro,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_BECA_VIGENCIA','STG_BECAS_VIGENCIA',q'~SELECT v.* FROM STG_BECAS_VIGENCIA v JOIN STG_BECAS b ON b.id_beca=v.id_beca JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=b.id_inscripcion JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE v.fecha_inicio<i.fecha_inicio OR v.fecha_inicio>COALESCE(i.fecha_fin,x.fecha_fin) OR (v.fecha_fin IS NOT NULL AND (v.fecha_fin<v.fecha_inicio OR v.fecha_fin>COALESCE(i.fecha_fin,x.fecha_fin))) OR (v.fecha_fin IS NULL AND v.motivo_fin IS NOT NULL) OR (v.fecha_fin IS NOT NULL AND v.motivo_fin IS NULL)~',q'~JSON_OBJECT('id_vigencia' VALUE q.id_vigencia,'id_beca' VALUE q.id_beca,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'motivo_fin' VALUE q.motivo_fin,'fecha_registro' VALUE q.fecha_registro,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_BECA_SOLAPADA','STG_BECAS_VIGENCIA',q'~SELECT v.* FROM STG_BECAS_VIGENCIA v JOIN STG_BECAS b ON b.id_beca=v.id_beca JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=b.id_inscripcion JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE EXISTS (SELECT 1 FROM STG_BECAS_VIGENCIA w WHERE w.id_beca=v.id_beca AND w.id_vigencia<>v.id_vigencia AND v.fecha_inicio<=COALESCE(w.fecha_fin,x.fecha_fin) AND w.fecha_inicio<=COALESCE(v.fecha_fin,x.fecha_fin))~',q'~JSON_OBJECT('id_vigencia' VALUE q.id_vigencia,'id_beca' VALUE q.id_beca,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'motivo_fin' VALUE q.motivo_fin,'fecha_registro' VALUE q.fecha_registro,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_PORCENTAJE_SIMULTANEO','STG_BECAS_VIGENCIA',q'~SELECT v.* FROM STG_BECAS_VIGENCIA v JOIN STG_BECAS b ON b.id_beca=v.id_beca JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=b.id_inscripcion JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE (SELECT SUM(z.porcentaje) FROM STG_BECAS_VIGENCIA w JOIN STG_BECAS z ON z.id_beca=w.id_beca WHERE z.id_inscripcion=b.id_inscripcion AND w.fecha_inicio<=v.fecha_inicio AND COALESCE(w.fecha_fin,x.fecha_fin)>=v.fecha_inicio)>100~',q'~JSON_OBJECT('id_vigencia' VALUE q.id_vigencia,'id_beca' VALUE q.id_beca,'fecha_inicio' VALUE q.fecha_inicio,'fecha_fin' VALUE q.fecha_fin,'motivo_fin' VALUE q.motivo_fin,'fecha_registro' VALUE q.fecha_registro,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');
    comprobar_regla('STAGING_CONTROL_CICLO','STG_CONTROL_CARGA',q'~SELECT z.* FROM STG_CONTROL_CARGA z JOIN STG_CURSOS c ON c.id_curso=z.id_curso JOIN STG_PERIODOS p ON p.id_periodo=z.id_periodo WHERE c.id_ciclo<>p.id_ciclo~',q'~JSON_OBJECT('id_control' VALUE q.id_control,'id_curso' VALUE q.id_curso,'id_periodo' VALUE q.id_periodo,'dominio' VALUE q.dominio,'fecha_corte' VALUE q.fecha_corte,'estado' VALUE q.estado,'registros_declarados' VALUE q.registros_declarados,'fecha_recepcion' VALUE q.fecha_recepcion,'id_ejecucion' VALUE q.id_ejecucion,'id_ejecucion_carga' VALUE q.id_ejecucion_carga,'fecha_carga' VALUE q.fecha_carga RETURNING CLOB)~');

    pr_validar_operacion('STAGING');
    UPDATE auditoria_etl_evaluaciones SET fin=LOCALTIMESTAMP,estado='COMPLETADA',
      total_leidos=v_leidos,insertados=v_insertados,actualizados=0,rechazados=0
      WHERE id_ejecucion=v_ejecucion;
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('Ejecución '||v_ejecucion||': '||v_insertados||' filas copiadas y verificadas.');
EXCEPTION WHEN OTHERS THEN
    v_codigo:=SQLCODE;v_mensaje:=SQLERRM;
    IF v_iniciada THEN ROLLBACK; END IF;
    IF v_ejecucion IS NOT NULL THEN
      BEGIN registrar_fallo;
      EXCEPTION WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('No pudo persistirse la auditoría: '||SQLERRM); END;
    END IF;
    RAISE;
END;
/

-- ==============================================================
-- Protección de las copias: un trigger por tabla STG
-- ==============================================================

-- === TRG_STG_CALIFICACIONES_INMUTABLE ===
CREATE OR REPLACE TRIGGER trg_stg_calificaciones_inmutable
 BEFORE INSERT OR UPDATE OR DELETE ON STG_CALIFICACIONES FOR EACH ROW
 DECLARE n NUMBER; BEGIN
  -- ----------------------------------------------------------------------
  -- TRG_STG_CALIFICACIONES_INMUTABLE: STG_CALIFICACIONES es una copia inmutable.
  --   - No se actualizan ni borran filas confirmadas (-20816).
  --   - Solo se insertan filas de una ejecución EN_PROCESO de auditoria_etl_evaluaciones,
  --     con fecha_carga entre el inicio de esa ejecución y el momento actual (-20816).
  -- ----------------------------------------------------------------------
 IF UPDATING OR DELETING THEN
  RAISE_APPLICATION_ERROR(-20816,'STG es copia inmutable; no editar ni borrar filas confirmadas.'); END IF;
 SELECT COUNT(*) INTO n FROM auditoria_etl_evaluaciones
 WHERE id_ejecucion=:NEW.id_ejecucion_carga AND estado='EN_PROCESO'
